INSERT INTO series (id, name, name_ja, description, source_url, retrieved_at) VALUES
(81, '初音ミク「マジカルミライ」', '初音ミク「マジカルミライ」', 'Hatsune Miku "Magical Mirai" (初音ミク「マジカルミライ」) is an annual festival organized by Crypton Future Media and Tokyo MX that celebrates the creative culture surrounding Hatsune Miku, both an exhibition and a 3DCG live show are held since 2013.', 'https://vocadb.net/Event/SeriesDetails/81', '2026-10-11T19:16:59.885Z'),
(82, 'MIKU EXPO', NULL, 'Miku Expo refers to a series of concert performances and venues featuring the Piapro characters (Hatsune Miku, Kagamine Rin, Kagamine Len, Megurine Luka, MEIKO and KAITO). There have been events in the United States, Mexico, China, Indonesia, Malaysia, and more.
2014 - present.', 'https://vocadb.net/Event/SeriesDetails/82', '2026-10-11T19:16:59.885Z'),
(173, 'MIKU WITH YOU', '初音未来·未来有你演唱会', 'A Hatsune Miku (Piapro Characters) concert series in Mainland China held by Crypton Future Media''s local copyright licensing agent Shanghai Character License Administrative Co., Ltd. (SCLA) and its partners', 'https://vocadb.net/Event/SeriesDetails/173', '2026-10-11T19:16:59.885Z'),
(256, '初音ミクシンフォニー', '初音ミクシンフォニー', 'Hatsune Miku Symphony (初音ミクシンフォニー) is a full orchestral concert which offers beautiful renditions of Hatsune Miku and VOCALOID songs.', 'https://vocadb.net/Event/SeriesDetails/256', '2026-10-11T19:16:59.885Z'),
(219, '初音ミクライブパーティー', '初音ミクライブパーティー', '', 'https://vocadb.net/Event/SeriesDetails/219', '2026-10-11T19:16:59.885Z'),
(204, 'SNOW MIKU LIVE!', NULL, '', 'https://vocadb.net/Event/SeriesDetails/204', '2026-10-11T19:16:59.885Z');
